var MT_CARGO_CORTO_ = {'Responsable de turno': 'Resp. de turno', 'Responsable de memoria': 'Resp. de memoria', 'Responsable audiovisual': 'Audiovisual', 'Coche': 'Coche'};   /* lo que se LEE en la ficha; el dato guarda el nombre entero */
